/* Ashyq Dala Partner Desk. Local-only, no network calls, no automatic fact matching. */
(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const plusDays=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:Number.isInteger(Number(n)||0)?0:2,maximumFractionDigits:2}).format(Number(n)||0);
const text=v=>String(v??'').slice(0,20000), short=v=>String(v??'').slice(0,600);
const emailOK=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
function safeURL(v){try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
const dateOK=v=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return !isNaN(d.getTime())&&d.toISOString().slice(0,10)===v;};
const STAGES=['New','Contacted','Conversation','Quoted','Active','Delivered','Lost'];
const MATCHES=['Unreviewed','Confirmed','Uncertain','Excluded'];
const RIGHTS=['Unchecked','Client-authorized','Public reuse checked','Licensed'];
const CATEGORIES=['Registration','Tax / finance','Procurement','Court records','Company documents','Media','Other'];
const TASKS=[['Write down 10 warm business contacts','Configure your email and export the offer','Send 15 individual, relevant messages','Hold 3 conversations about active deals','Agree scope and request a first deposit'],['Follow up once with week-one prospects','Deliver the first brief within its agreed scope','Track actual research hours and expenses','Ask the customer for one introduction','Pitch a second job at the full pilot price'],['Contact 15 more carefully selected prospects','Ask satisfied buyers about their next transaction','Raise the price if delivery takes too long','Review collected cash and costs','Keep, narrow, or change the offer based on paid work']];
let prospects=[];try{prospects=JSON.parse($('#prospect-data').textContent)}catch{}
const defaults=()=>({version:1,settings:{operator:'',email:'',bookingUrl:'',paymentUrl:'',price:250,goal:1000,hourlyValue:25,startDate:today()},leads:[],cases:[],tasks:[]});
let storage=true, own=defaults(), recoveryRaw=null;
try{const saved=localStorage.getItem('ashyq-dala-desk-v1');if(saved){try{own=normalizeState(JSON.parse(saved))}catch{recoveryRaw=saved;storage=false}}}catch{storage=false}
let demo=false, state=own, view='home', selectedCase=null, search='', stageFilter='All', toastTimer;
function save(){if(!demo){own=state;if(recoveryRaw===null)try{localStorage.setItem('ashyq-dala-desk-v1',JSON.stringify(state));storage=true}catch{storage=false}}$('#save-state').textContent=demo?'Example data · Separate from your work':recoveryRaw!==null?'Recovery mode · Original data preserved':storage?'Saved on this device':'Temporary session · Download a backup';}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function demoState(){const s=defaults();s.settings={...s.settings,operator:'Example analyst',goal:1500};s.leads=[{id:'demo-lead-1',client:'Example machinery exporter',email:'',company:'Steppe Equipment Example LLP',stage:'Active',fee:250,received:125,cost:18,hours:2.5,followup:today(),next:'Request the dated company extract',notes:'Fictional opportunity for demonstration.',createdAt:today()},{id:'demo-lead-2',client:'Example industrial supplier',email:'',company:'Illustrative Distribution LLP',stage:'Conversation',fee:250,received:0,cost:0,hours:0,followup:plusDays(1),next:'Confirm company identifier and decision deadline',notes:'Fictional opportunity.',createdAt:today()},{id:'demo-lead-3',client:'Example export agency',email:'',company:'Demo Parts LLP',stage:'Quoted',fee:250,received:0,cost:0,hours:0,followup:plusDays(2),next:'Follow up on agreed scope',notes:'Fictional opportunity.',createdAt:today()}];s.cases=[sampleCase()];return s}
function sampleCase(){return {id:'sample-case',synthetic:true,leadId:'demo-lead-1',company:'Steppe Equipment Example LLP',bin:'',client:'Example machinery exporter',goal:'Understand which company would sign the proposed distribution agreement.',deadline:plusDays(2),summary:'The illustrative company extract and draft agreement use different legal-entity names. The signing entity remains unresolved. This example shows how evidence and missing information are separated; it makes no claim about any real company.',recommendations:'Ask the counterparty to confirm the signing legal entity and provide its current company extract.\nRequest an updated draft agreement with consistent company details.\nRefer legal and sanctions questions to the appropriate qualified adviser.',limitations:'Fictional demonstration. No registry, court, tax, ownership, or sanctions source was searched. No conclusions about financial standing or compliance can be drawn.',notes:'Internal notes are excluded from client exports.',analyst:'Example analyst',signedOff:true,createdAt:today(),updatedAt:today(),sources:[{id:'sample-1',title:'Illustrative company extract',category:'Company documents',url:'',reference:'FICTIONAL DOCUMENT A',accessed:today(),sourceDate:today(),recordBin:'',recordName:'Steppe Equipment Example LLP',claim:'The fictional extract names Steppe Equipment Example LLP. It does not establish which entity would sign the agreement.',match:'Confirmed',permission:'Client-authorized',reviewNote:'The fictional buyer explicitly supplied this document for the illustrative subject.'},{id:'sample-2',title:'Illustrative draft agreement',category:'Company documents',url:'',reference:'FICTIONAL DOCUMENT B',accessed:today(),sourceDate:today(),recordBin:'',recordName:'Steppe Equipment Example Trading LLP',claim:'The fictional draft names a different entity. Attribution is unresolved and is not treated as a finding against the subject.',match:'Uncertain',permission:'Client-authorized',reviewNote:'Different entity name; awaiting clarification.'}]}}
function normalizeState(raw){
  const obj=(x,label)=>{if(!x||typeof x!=='object'||Array.isArray(x))throw Error(label+' must be an object.');return x};
  const num=(v,fallback,min,max,label)=>{if(v===undefined||v===null||v==='')return fallback;const n=Number(v);if(!Number.isFinite(n)||n<min||n>max)throw Error('Invalid '+label+'.');return n};
  const str=(v,max=20000)=>{if(v!==undefined&&v!==null&&typeof v!=='string')throw Error('Expected text field.');if((v||'').length>max)throw Error('Text field exceeds supported length.');return v||''};
  const dt=v=>{v=str(v,10);if(v&&!dateOK(v))throw Error('Invalid calendar date.');return v};
  const bin=v=>{v=str(v,12);if(v&&!/^[0-9]{12}$/.test(v))throw Error('Invalid BIN format.');return v};
  const arr=(v,max,label)=>{if(!Array.isArray(v)||v.length>max)throw Error(label+' must contain at most '+max+' items.');return v};
  const ids=new Set();const getId=(v,prefix)=>{v=str(v,600);if(!v)throw Error('Missing record ID.');const k=prefix+v;if(ids.has(k))throw Error('Duplicate record ID.');ids.add(k);return v};
  obj(raw,'Workspace');if(raw.version!==1)throw Error('Unsupported workspace version.');const s=defaults(),r=obj(raw.settings||{},'Settings');
  s.settings={operator:str(r.operator,600),email:str(r.email,600),bookingUrl:safeURL(r.bookingUrl),paymentUrl:safeURL(r.paymentUrl),price:num(r.price,250,25,100000,'price'),goal:num(r.goal,1000,1,10000000,'target'),hourlyValue:num(r.hourlyValue,25,0,10000,'hourly value'),startDate:dt(r.startDate)||today()};
  s.leads=arr(raw.leads,1000,'Leads').map(x=>{obj(x,'Lead');const fee=num(x.fee,0,0,10000000,'fee');return {id:getId(x.id,'lead:'),client:str(x.client,600),email:str(x.email,600),company:str(x.company,600),stage:STAGES.includes(x.stage)?x.stage:'New',fee,received:num(x.received,0,0,fee,'receipt'),cost:num(x.cost,0,0,10000000,'cost'),hours:num(x.hours,0,0,100000,'hours'),followup:dt(x.followup),next:str(x.next,600),notes:str(x.notes),createdAt:dt(x.createdAt)}});
  s.cases=arr(raw.cases,500,'Cases').map(x=>{obj(x,'Case');const id=getId(x.id,'case:');return {id,leadId:str(x.leadId,600),synthetic:x.synthetic===true,company:str(x.company,600),bin:bin(x.bin),client:str(x.client,600),goal:str(x.goal),deadline:dt(x.deadline),summary:str(x.summary),recommendations:str(x.recommendations),limitations:str(x.limitations),notes:str(x.notes),analyst:str(x.analyst,600),signedOff:x.signedOff===true,createdAt:dt(x.createdAt),updatedAt:dt(x.updatedAt),sources:arr(x.sources,500,'Sources per case').map(z=>{obj(z,'Source');return {id:getId(z.id,'source:'+id+':'),title:str(z.title,600),category:CATEGORIES.includes(z.category)?z.category:'Other',url:safeURL(z.url),reference:str(z.reference,600),accessed:dt(z.accessed),sourceDate:dt(z.sourceDate),recordBin:bin(z.recordBin),recordName:str(z.recordName,600),claim:str(z.claim),match:MATCHES.includes(z.match)?z.match:'Unreviewed',permission:RIGHTS.includes(z.permission)?z.permission:'Unchecked',reviewNote:str(z.reviewNote)}})}});
  s.tasks=arr(raw.tasks||[],15,'Launch tasks').filter(n=>Number.isInteger(n)&&n>=0&&n<15);return s;
}
const badge=(v,kind='')=>`<span class="badge ${kind}">${esc(v)}</span>`;
const stageBadge=s=>badge(s,['Active','Delivered'].includes(s)?'green':s==='Quoted'?'gold':'');
const options=(arr,value)=>arr.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const area=(label,name,value='',extra='')=>`<div class="field full"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;
function heading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions}</div>`}
function empty(title,desc,button=''){return `<div class="empty"><div class="empty-icon">↗</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${button}</div>`}
const action=(a,label,cls='',id='')=>`<button class="btn ${cls}" data-action="${a}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
function render(){save();const names={home:'Overview',pipeline:'Sales pipeline',cases:'Research desk',prospects:'Find your first clients',launch:'21-day launch',settings:'Offer & settings'};$('#breadcrumb').textContent='Workspace / '+names[view];$$('nav [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#sample-toggle').textContent=demo?'Return to my work':'Explore example';$('#mode-banner').hidden=!demo;$('#mode-banner').innerHTML='FICTIONAL EXAMPLE · No real clients, payments, or company findings. <button class="text-button" data-action="toggle-demo">Return to my work →</button>';$('#main').innerHTML=({home:renderHome,pipeline:renderPipeline,cases:renderCases,prospects:renderProspects,launch:renderLaunch,settings:renderSettings}[view])();}
function stats(){return {cash:state.leads.reduce((s,x)=>s+x.received,0),agreed:state.leads.filter(x=>['Active','Delivered'].includes(x.stage)).reduce((s,x)=>s+x.fee,0),earned:state.leads.filter(x=>x.stage==='Delivered').reduce((s,x)=>s+x.fee,0),costs:state.leads.reduce((s,x)=>s+x.cost,0),hours:state.leads.reduce((s,x)=>s+x.hours,0),open:state.leads.filter(x=>!['Delivered','Lost'].includes(x.stage)).length,active:state.leads.filter(x=>x.stage==='Active').length}}
function renderHome(){const s=stats(),due=state.leads.filter(x=>x.followup&&x.followup<=today()&&!['Delivered','Lost'].includes(x.stage)),setup=emailOK(state.settings.email);const checks=[[setup,'Make your offer reachable','Set your receiving email, then export your sales page.','settings'],[state.leads.length>0,'Start with a live transaction','Add a warm contact or choose a researched prospect.','prospects'],[s.cash>0,'Agree scope. Collect a deposit.','Confirm access and delivery terms before taking payment.','pipeline']];return (recoveryRaw!==null?`<div class="note"><strong>Stored workspace needs recovery.</strong> The original data has been preserved. ${action('recover-data','Download original data','small')} ${action('clear-work','Start a new workspace','small danger')}</div>`:'')+heading('A SMALL SERVICE. A REAL BUSINESS.','Build toward your first paid brief.','One clear offer, a focused sales routine, and a report you can confidently deliver.')+`<div class="metrics">${[['Cash received',money(s.cash),'Manually logged receipts'],['Agreed fees',money(s.agreed),'Active + delivered jobs'],['Open opportunities',s.open,'People you have added'],['In delivery',s.active,'Active paid-service jobs']].map(([a,b,c])=>`<div class="card metric"><div class="metric-label">${a}<span>↗</span></div><div class="metric-value">${b}</div><small>${c}</small></div>`).join('')}</div><div class="home-grid"><section class="card hero-panel"><div class="eyebrow">YOUR FIRST OFFER</div><h2>Kazakhstan partner research.<br>A clear next step in 2 days.</h2><p>One company. Dated evidence. Document discrepancies. The questions a buyer still needs answered.</p><div class="row">${action('preview-offer','Preview your sales page ↗','gold')}${action('sample-report','View sample brief','quiet')}</div></section><section class="card"><div class="card-top"><h2>Start here</h2>${badge('3 practical steps')}</div><div class="checklist">${checks.map(([done,t,d,v],i)=>`<div class="check-item"><span class="check-number ${done?'done':''}">${done?'✓':i+1}</span><div><strong><button class="text-button" data-view="${v}">${t}</button></strong><p>${d}</p></div></div>`).join('')}</div></section></div><div class="home-grid"><section class="card"><div class="card-top"><h2>Your next conversations</h2>${action('new-lead','+ Add opportunity','small')}</div>${due.length?leadTable(due):empty('No follow-ups due','Set a next action and follow-up date on every opportunity. A useful conversation is your next milestone.',`<button class="btn" data-view="prospects">Explore researched prospects →</button>`)}</section><section class="card"><div class="card-top"><h2>Your cash target</h2>${action('settings','Edit','small')}</div><div class="row between"><span class="muted tiny">${money(s.cash)} collected</span><strong>${money(state.settings.goal)}</strong></div><div class="progress"><span style="width:${Math.min(100,100*s.cash/state.settings.goal)}%"></span></div><p class="tiny">${Math.ceil(Math.max(0,state.settings.goal-s.cash)/state.settings.price)} more fully paid briefs at ${money(state.settings.price)} would reach this target. This is arithmetic, not a sales forecast.</p><div class="money-details"><div><strong>${money(s.earned)}</strong><small>Delivered revenue</small></div><div><strong>${money(s.costs)}</strong><small>Logged direct costs</small></div><div><strong>${s.hours.toFixed(1)}h</strong><small>Logged work time</small></div></div><p class="tiny section-gap">Deposits are cash received for work still owed. These figures are not an accounting profit statement.</p></section></div>`}
function leadTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Stage</th><th>Next action</th><th class="num">Received / fee</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.client)}</strong><small>${esc(x.company||'Company to confirm')}</small></td><td>${stageBadge(x.stage)}</td><td>${esc(x.next||'Set a next action')}<small>${esc(x.followup||'No follow-up date')}</small></td><td class="num no-wrap">${money(x.received)} / ${money(x.fee)}</td><td>${action('edit-lead','Open','small',x.id)}</td></tr>`).join('')}</tbody></table></div>`}
function renderPipeline(){let rows=state.leads.filter(x=>(stageFilter==='All'||x.stage===stageFilter)&&(`${x.client} ${x.company} ${x.next}`).toLowerCase().includes(search.toLowerCase()));return heading('RELATIONSHIPS BEFORE SOFTWARE','Every lead needs a next step.','Track your own conversations, agreed jobs, receipts, time, and costs.',`<div class="row">${action('import','Import request','quiet')}${action('new-lead','+ New opportunity','dark')}</div>`)+`<section class="card"><div class="toolbar"><input aria-label="Search opportunities" id="lead-search" placeholder="Search client or company…" value="${esc(search)}"><select style="max-width:190px" aria-label="Filter stage" id="stage-filter">${options(['All',...STAGES],stageFilter)}</select></div>${rows.length?leadTable(rows):empty('Your next customer starts here','Add someone with a current Kazakhstan transaction. Quote only the work you can actually deliver.',action('new-lead','Add an opportunity','dark'))}</section><div class="note section-gap">Payment figures are records you enter yourself. This app does not process payments or verify bank receipts.</div>`}
function currentCase(){return state.cases.find(x=>x.id===selectedCase)||state.cases[0]}
function readiness(c){const inc=c.sources.filter(x=>x.match!=='Excluded');return [{ok:!!(c.company.trim()&&c.client.trim()),label:'Client and subject company identified'},{ok:!!(c.summary.trim()&&c.recommendations.trim()&&c.limitations.trim()),label:'Summary, next steps, and limitations written'},{ok:inc.some(x=>x.match==='Confirmed'),label:'At least one source attributed by the analyst'},{ok:inc.every(x=>x.match!=='Unreviewed')&&c.sources.length>0,label:'All records reviewed or explicitly excluded'},{ok:inc.every(x=>x.title&&x.claim&&(safeURL(x.url)||x.reference)&&dateOK(x.accessed)&&x.permission!=='Unchecked'),label:'Included evidence has a source, access date, and checked use rights'},{ok:inc.filter(x=>x.match==='Confirmed').every(x=>!conflict(c,x)&&(sameBIN(c,x)||x.reviewNote.trim())),label:'No confirmed identifier conflicts; manual attribution explained'},{ok:!!(c.signedOff&&c.analyst.trim()),label:'Analyst has completed the final review'}]}
function sameBIN(c,s){return /^[0-9]{12}$/.test(c.bin)&&s.recordBin===c.bin}
function conflict(c,s){return !!(c.bin&&s.recordBin&&c.bin!==s.recordBin)}
function ready(c){return readiness(c).every(x=>x.ok)}
function renderCases(){const c=currentCase();if(c)selectedCase=c.id;return heading('EVIDENCE, THEN CONCLUSIONS','Make the work worth paying for.','Review every source. Explain every uncertainty. Keep internal notes out of client reports.',`<div class="row">${action('sample-report','Sample brief','quiet')}${action('new-case','+ New case','dark')}</div>`)+(!c?`<section class="card">${empty('Open your first research case','Start with the exact company and the buyer’s decision. No record is linked or treated as verified automatically.',action('new-case','Create a case','dark'))}</section>`:`<div class="case-grid"><div class="case-list">${state.cases.map(x=>`<button class="case-button ${x.id===c.id?'selected':''}" data-action="select-case" data-id="${esc(x.id)}"><strong>${esc(x.company||'Untitled case')}</strong><small>${esc(x.client||'Client not set')}</small><div style="margin-top:10px">${badge(x.synthetic?'Fictional example':ready(x)?'Reviewed':'Draft',ready(x)?'green':'gold')} <span class="tiny muted">${x.sources.length} sources</span></div></button>`).join('')}</div><div class="case-detail"><section class="card"><div class="card-top"><div><div class="eyebrow">${c.synthetic?'FICTIONAL EXAMPLE':'RESEARCH CASE'}</div><h2 style="margin-top:7px">${esc(c.company)}</h2></div>${action('edit-case','Edit case','small',c.id)}</div><p class="tiny break">${esc(c.goal||'Define the question this research should answer.')}</p><div class="case-meta"><span>For ${esc(c.client||'Client to confirm')}</span><span>BIN ${esc(c.bin||'not supplied')}</span><span>Due ${esc(c.deadline||'to agree')}</span></div></section><section class="card section-gap"><div class="card-top"><h2>Evidence ledger</h2><div class="row">${action('csv-import','Import CSV','small',c.id)}${action('new-evidence','+ Add source','small dark',c.id)}</div></div><p class="tiny">“Confirmed” means you accepted the source’s attribution to this company. It does not guarantee the source is accurate or complete.</p>${c.sources.length?c.sources.map(s=>`<article class="evidence"><div class="row between"><h3>${esc(s.title)}</h3><div class="row">${badge(s.match,s.match==='Confirmed'?'green':s.match==='Uncertain'?'gold':'')}${conflict(c,s)?badge('BIN conflict','red'):''}</div></div><p>${esc(s.claim)}</p><div class="evidence-foot"><span>${esc(s.category)} · Accessed ${esc(s.accessed||'not recorded')} · ${esc(s.permission)}</span>${action('edit-evidence','Review','small',s.id)}</div></article>`).join(''):empty('Build a traceable brief','Add source URLs or document references. Imported records always need your review.')}<p class="tiny section-gap">Do not enter national ID numbers, home addresses, or unrelated personal records. A public source is not automatically licensed for redistribution.</p></section><section class="card section-gap"><div class="card-top"><h2>Your assessment</h2>${badge('Written by you')}</div><form data-form="assessment" data-id="${esc(c.id)}"><div class="form-grid">${area('Summary for the client','summary',c.summary)}${area('Questions and next steps (one per line)','recommendations',c.recommendations)}${area('Coverage gaps and limitations','limitations',c.limitations)}${area('Internal notes · never included in the client brief','notes',c.notes)}${field('Analyst name','analyst',c.analyst||state.settings.operator)}<div class="field"><label class="checkbox" style="margin-top:22px"><input type="checkbox" name="signedOff" ${c.signedOff?'checked':''}>I have reviewed the evidence, attribution, use rights, and wording.</label></div></div><div class="form-actions"><button class="btn dark">Save assessment</button></div></form></section><section class="card section-gap"><div class="card-top"><h2>Client deliverable</h2>${badge(ready(c)?'Review complete':'Draft',ready(c)?'green':'gold')}</div><div class="readiness">${readiness(c).map(r=>`<div><span style="color:${r.ok?'#537747':'#a07845'}">${r.ok?'✓':'○'}</span><span>${r.label}</span></div>`).join('')}</div><div class="row section-gap">${action('preview-report','Preview brief','',c.id)}${action('export-report',ready(c)?'Download reviewed brief ↗':'Download draft ↗','dark',c.id)}${action('copy-report','Copy text','quiet',c.id)}${action('document-request','Document request','quiet',c.id)}</div></section></div></div>`)}
function renderProspects(){return heading('A STARTING LIST, NOT GUARANTEED BUYERS','Approach a relevant person.','Publicly researched companies with a Kazakhstan or regional connection. Confirm an active need before pitching.')+`<div class="note green"><strong>Start with warm introductions.</strong> Use existing supplier or factory relationships first. These cold prospects are unqualified, and some already have their own research capabilities.</div><div class="lead-grid">${prospects.map((p,i)=>`<article class="card lead-card"><div class="row between"><span class="eyebrow">${esc(p.priority||'Research prospect')}</span>${badge('Uncontacted')}</div><h2>${esc(p.company)}</h2><p>${esc(p.reason)}</p><div><div class="subhead">Person to ask for</div><p>${esc(p.role)}</p></div><div><div class="subhead">Conversation angle</div><p>${esc(p.angle)}</p></div><div class="row">${safeURL(p.url)?`<a class="btn small" href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}${safeURL(p.contactUrl)?`<a class="btn small" href="${esc(safeURL(p.contactUrl))}" target="_blank" rel="noopener noreferrer">Contact page ↗</a>`:''}${action('use-prospect','Add to pipeline','small dark',String(i))}</div></article>`).join('')}</div>`}
const outreach=(name='[Name]')=>`Hi ${name},\n\nAre you currently evaluating a customer, distributor, or supplier in Kazakhstan?\n\nI’m offering a focused company research brief: dated sources, discrepancies in the documents you provide, and the questions still needing answers. One company, ${money(state.settings.price)}, delivered within two business days after we confirm source access, scope, and documents.\n\nIf you have a live transaction, what do you need to clarify before the next step? I can send a clearly labelled sample.\n\n${state.settings.operator||'[Your name]'}`;
function renderLaunch(){const s=stats(),net=s.earned-s.costs-s.hours*state.settings.hourlyValue;return heading('21 DAYS · SELL, DELIVER, LEARN','A practical route to first revenue.','These are activity targets and pricing experiments. Customer demand and payment timing remain uncertain.')+`<div class="launch-grid">${TASKS.map((tasks,w)=>`<section class="card launch-week"><div class="week-number">0${w+1}</div><div class="eyebrow">DAYS ${w*7+1}–${w*7+7}</div><h2 style="margin:8px 0 17px">${['Find the live need.','Deliver a paid pilot.','Repeat what worked.'][w]}</h2>${tasks.map((t,i)=>`<label class="launch-task ${state.tasks.includes(w*5+i)?'complete':''}"><input type="checkbox" data-task="${w*5+i}" ${state.tasks.includes(w*5+i)?'checked':''}><span>${t}</span></label>`).join('')}</section>`).join('')}</div><div class="split section-gap"><section class="card"><div class="card-top"><h2>Your first message</h2>${action('copy-outreach','Copy','small')}</div><div class="message-box">${esc(outreach())}</div><p class="tiny section-gap">Personalize the first sentence using a real, relevant detail. Nothing is sent automatically.</p></section><section class="card"><h2>Protect your time and margin.</h2><p class="tiny section-gap">At ${money(state.settings.price)}, four completed jobs produce ${money(4*state.settings.price)} of revenue before expenses and tax. Keep the scope to one company and record every hour, including sales.</p><div class="money-details"><div><strong>${money(s.earned)}</strong><small>Delivered fees</small></div><div><strong>${money(s.costs)}</strong><small>Direct costs</small></div><div><strong>${money(net)}</strong><small>After logged time at ${money(state.settings.hourlyValue)}/h</small></div></div><p class="tiny section-gap">The last figure is a management estimate, not accounting profit; incomplete hours or costs overstate it. Undelivered job costs are included.</p><div class="note section-gap"><strong>Decision point:</strong> after five substantive conversations with buyers who have an active need, examine why they will or won’t pay. No replies means revisit targeting and messaging. No paid pilot by day 14 means change the offer or buyer before doing more development.</div></section></div>`}
function renderSettings(){const s=state.settings;return heading('YOUR OFFER, READY TO SHARE','Set up the path to getting paid.','The exported sales page contains only public offer settings. Your cases, leads, and internal notes stay in this workspace.')+`<div class="settings-grid"><section class="card"><h2>Business details</h2><form data-form="settings" class="section-gap"><div class="form-grid">${field('Your name / analyst name','operator',s.operator,'text','maxlength="120"')}${field('Receiving email','email',s.email,'email','required')}${field('Pilot price (USD)','price',s.price,'number','min="25" max="100000" required step="1"')}${field('21-day cash target (USD)','goal',s.goal,'number','min="1" max="10000000" required step="1"')}${field('Your time value (USD/hour)','hourlyValue',s.hourlyValue,'number','min="0" max="10000" step="1"')}${field('Campaign start date','startDate',s.startDate,'date','required')}${field('Booking link (optional, HTTPS)','bookingUrl',s.bookingUrl,'url')}${field('Payment link for agreed proposals (optional, HTTPS)','paymentUrl',s.paymentUrl,'url')}<div class="field full"><small>Use a payment link you control. Confirm currency and deposit amount in your payment provider. It appears only on proposals for active or delivered jobs. This app does not create invoices, process charges, or verify receipts.</small></div></div><div class="form-actions"><button class="btn dark">Save settings</button></div></form></section><div><section class="card"><div class="eyebrow">YOUR PUBLIC OFFER</div><h2 style="margin:10px 0">One brief. One decision.</h2><p class="tiny">A standalone sales page with scope, a fictional sample, and a request form that prepares an email draft. No visitor submission is stored on a server.</p><div class="row section-gap">${action('preview-offer','Preview','')}${action('export-offer','Export sales page ↗','dark')}</div><p class="tiny section-gap">Add a valid receiving email before exporting. Publish only the exported sales page; keep this desk and your backups private.</p></section><section class="card section-gap"><h2>Your work, under your control.</h2><p class="tiny section-gap">Saved in this browser when available. There is no login, cloud sync, encryption, or live data feed. Use a private device and secure backups; clear shared-device storage after use.</p><div class="row section-gap">${action('backup','Download backup','')}${action('import','Restore / import request','')}</div><div class="section-gap">${action('clear-work','Clear workspace','danger small')}</div></section></div></div>`}
function showDialog(title,content){$('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-content">${content}</div>`;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close()}
function leadDialog(id,seed={}){const x=state.leads.find(x=>x.id===id)||{client:'',email:'',company:'',stage:'New',fee:state.settings.price,received:0,cost:0,hours:0,followup:today(),next:'Ask about a live Kazakhstan transaction',notes:'',...seed};showDialog(id?'Opportunity details':'New opportunity',`<form data-form="lead" data-id="${esc(id||'')}"><div class="form-grid">${field('Client / prospect organization','client',x.client,'text','required maxlength="200"')}${field('Contact email (optional)','email',x.email,'email')}${field('Company to research','company',x.company,'text','maxlength="250"')}<div class="field"><label for="f-stage">Stage</label><select id="f-stage" name="stage">${options(STAGES,x.stage)}</select></div>${field('Fee quoted / agreed (USD)','fee',x.fee,'number','required min="0" max="10000000" step="0.01"')}${field('Cash actually received (USD)','received',x.received,'number','required min="0" step="0.01"')}${field('Direct costs paid (USD)','cost',x.cost,'number','required min="0" max="10000000" step="0.01"')}${field('Total hours spent (sales + delivery)','hours',x.hours,'number','required min="0" max="100000" step="0.25"')}${field('Follow-up date','followup',x.followup,'date')}${field('Next action','next',x.next,'text','maxlength="300"')}${area('Internal notes','notes',x.notes)}</div><div class="form-actions">${id?action('quote','Proposal','',id)+action('lead-case','Open research case','',id):''}<button class="btn dark">Save opportunity</button></div>${id?`<div class="section-gap">${action('delete-lead','Delete opportunity','danger small',id)}</div>`:''}</form>`)}
function caseDialog(id,seed={}){const c=state.cases.find(x=>x.id===id)||{company:'',bin:'',client:'',goal:'',deadline:'',...seed};showDialog(id?'Case details':'New research case',`<form data-form="case" data-id="${esc(id||'')}" data-lead="${esc(c.leadId||'')}"><div class="form-grid">${field('Subject company name','company',c.company,'text','required maxlength="250"')}${field('BIN (optional; 12 ASCII digits)','bin',c.bin,'text','pattern="[0-9]{12}" maxlength="12" inputmode="numeric"')}${field('Client organization','client',c.client,'text','required maxlength="250"')}${field('Agreed due date','deadline',c.deadline,'date')}${area('What decision / question should this brief address?','goal',c.goal,'required')}</div><p class="tiny section-gap">A 12-digit format does not authenticate a company or establish source attribution. Confirm identity with appropriate records.</p><div class="form-actions"><button class="btn dark">Save case</button></div>${id?`<div class="section-gap">${action('delete-case','Delete case','danger small',id)}</div>`:''}</form>`)}
function evidenceDialog(id){const c=currentCase(),s=c.sources.find(x=>x.id===id)||{title:'',category:'Registration',url:'',reference:'',accessed:today(),sourceDate:'',recordBin:'',recordName:'',claim:'',match:'Unreviewed',permission:'Unchecked',reviewNote:''};showDialog(id?'Review source':'Add source',`<form data-form="evidence" data-id="${esc(id||'')}"><div class="note">Do not confirm a name-only match without a reason. A conflicting BIN cannot be confirmed. Check permission before including material in a client report.</div><div class="form-grid">${field('Source title','title',s.title,'text','required maxlength="250"')}<div class="field"><label for="f-category">Category</label><select name="category" id="f-category">${options(CATEGORIES,s.category)}</select></div>${field('Source URL (HTTPS)','url',s.url,'url')}${field('Document reference (if no URL)','reference',s.reference,'text','maxlength="300"')}${field('Date accessed / received','accessed',s.accessed,'date','required')}${field('Source publication / document date','sourceDate',s.sourceDate,'date')}${field('Company name in this record','recordName',s.recordName)}${field('BIN in this record (if present)','recordBin',s.recordBin,'text','pattern="[0-9]{12}" maxlength="12" inputmode="numeric"')}${area('What does this source actually say?','claim',s.claim,'required')}<div class="field"><label for="f-match">Attribution review</label><select id="f-match" name="match">${options(MATCHES,s.match)}</select></div><div class="field"><label for="f-permission">Use rights checked</label><select id="f-permission" name="permission">${options(RIGHTS,s.permission)}</select></div>${area('Attribution rationale / limitations','reviewNote',s.reviewNote)}</div><div class="form-actions">${id?action('delete-evidence','Delete source','danger',id):''}<button class="btn dark">Save source</button></div></form>`)}
function csvDialog(){showDialog('Import evidence CSV',`<p class="tiny">Headers: title, category, url, reference, accessed, sourceDate, recordBin, recordName, claim. Quoted fields and line breaks are supported. Imports are always Unreviewed with Unchecked use rights. Limit: 500 rows.</p><form data-form="csv" class="section-gap"><div class="field"><label for="csv-text">Paste CSV</label><textarea id="csv-text" name="csv" rows="10" required placeholder="title,category,url,reference,accessed,sourceDate,recordBin,recordName,claim"></textarea></div><div class="row section-gap"><label class="btn small">Choose CSV file<input id="csv-file" type="file" accept=".csv,text/csv" hidden></label>${action('csv-template','Download template','small')}</div><div class="form-actions"><button class="btn dark">Import for review</button></div></form>`)}
function parseCSV(src){src=src.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++}else if(quoted){quoted=false}else if(cell===''){quoted=true}else throw Error('Unexpected quote in CSV. Quote the whole field.')}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c;}if(quoted)throw Error('CSV contains an unclosed quoted field.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function doCSV(src){if(src.length>2000000)throw Error('CSV is too large. Limit: 2 MB.');const rows=parseCSV(src),headers=(rows.shift()||[]).map(x=>x.trim());if(!headers.includes('title')||!headers.includes('claim'))throw Error('CSV needs title and claim headers.');if(rows.length>500||currentCase().sources.length+rows.length>500)throw Error('A case can contain at most 500 evidence records.');if(!rows.length)throw Error('No evidence rows found.');const imported=rows.map((row,i)=>{if(row.length!==headers.length)throw Error(`Row ${i+2}: column count does not match headers.`);const data={};headers.forEach((h,j)=>{if(['title','category','url','reference','accessed','sourceDate','recordBin','recordName','claim'].includes(h))data[h]=row[j].trim()});if(!data.title||!data.claim)throw Error(`Row ${i+2}: title and claim are required.`);if(data.url&&!safeURL(data.url))throw Error(`Row ${i+2}: source URL must use HTTPS.`);if(data.recordBin&&!/^[0-9]{12}$/.test(data.recordBin))throw Error(`Row ${i+2}: BIN must contain 12 ASCII digits.`);for(const k of ['accessed','sourceDate'])if(data[k]&&!dateOK(data[k]))throw Error(`Row ${i+2}: ${k} must be YYYY-MM-DD.`);return {id:uid(),title:short(data.title),category:CATEGORIES.includes(data.category)?data.category:'Other',url:safeURL(data.url),reference:short(data.reference),accessed:data.accessed||'',sourceDate:data.sourceDate||'',recordBin:short(data.recordBin),recordName:short(data.recordName),claim:text(data.claim),match:'Unreviewed',permission:'Unchecked',reviewNote:''}});const c=currentCase();c.sources.push(...imported);c.signedOff=false;c.updatedAt=today();closeDialog();render();toast(`${imported.length} sources imported for review.`)}
function reportBody(c){const usable=x=>x.permission!=='Unchecked'&&x.title&&x.claim&&(safeURL(x.url)||x.reference)&&dateOK(x.accessed);const reviewed=ready(c),included=c.sources.filter(x=>x.match==='Confirmed'&&!conflict(c,x)&&usable(x)),uncertain=c.sources.filter(x=>x.match==='Uncertain'&&usable(x));const stamp=c.synthetic||demo?'FICTIONAL SAMPLE · All companies, records, and findings below are invented.':!reviewed?'DRAFT · Review incomplete. Not a final client deliverable.':'';const renderSources=arr=>arr.length?arr.map((s,i)=>`<article class="evidence"><h3>${i+1}. ${esc(s.title)}</h3><p>${esc(s.claim)}</p><p><strong>Source:</strong> ${s.url?`<a href="${esc(safeURL(s.url))}" rel="noopener noreferrer">${esc(s.url)}</a>`:esc(s.reference)}<br><strong>Accessed:</strong> ${esc(s.accessed||'not recorded')} · <strong>Source date:</strong> ${esc(s.sourceDate||'not stated')}<br><strong>Category:</strong> ${esc(s.category)} · <strong>Attribution:</strong> ${esc(s.match)} by analyst</p>${s.reviewNote?`<p><strong>Attribution note:</strong> ${esc(s.reviewNote)}</p>`:''}</article>`).join(''):'<p>No reviewed evidence in this category.</p>';return `${stamp?`<div class="stamp">${stamp}</div>`:''}<div class="eyebrow">ASHYQ DALA / COMPANY RESEARCH BRIEF</div><h1>${esc(c.company)}</h1><p>Prepared for ${esc(c.client)} · ${esc(today())}<br>Analyst: ${esc(c.analyst||'Not recorded')} · BIN: ${esc(c.bin||'Not supplied')}<br>Status: ${reviewed?'Analyst review complete':'Draft'}</p><h2>Research question</h2><p>${esc(c.goal||'Not recorded.')}</p><h2>Executive summary</h2><p>${esc(c.summary||'Assessment not yet written.')}</p><h2>Evidence attributed to the subject</h2>${renderSources(included)}${uncertain.length?`<h2>Unresolved attribution</h2><p>These sources are not established as referring to the subject. They must not be treated as adverse findings against it.</p>${renderSources(uncertain)}`:''}<h2>Questions and next steps</h2><ul>${(c.recommendations||'Next steps not yet written.').split('\n').filter(Boolean).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h2>Coverage and limitations</h2><p>${esc(c.limitations||'Limitations not yet recorded.')}</p><p>This is a scoped commercial research brief, based only on the evidence described above. It is not a legal opinion, credit rating, sanctions clearance, or guarantee of safety. No automated risk score is assigned. Missing information is not evidence that no issue exists.</p><h2>Source coverage</h2><p>${c.sources.length} record(s) logged: ${included.length} attributed, ${uncertain.length} unresolved, ${c.sources.filter(x=>x.match==='Excluded').length} excluded, ${c.sources.filter(x=>x.match==='Unreviewed').length} unreviewed. Excluded, unreviewed, and incomplete or permission-unchecked contents are not included in this brief. Confirmed records with identifier conflicts are also withheld.</p><p style="margin-top:30px;font-size:10px">Ashyq Dala · Prepared for the named client · Source availability and facts can change after the stated dates.</p>`}
const reportCSS='body{max-width:850px;margin:45px auto;padding:0 30px;color:#19362c;font:14px/1.7 Arial,sans-serif}h1{font:38px Georgia;margin:16px 0}h2{font:24px Georgia;margin:28px 0 10px;border-bottom:1px solid #dce4d8;padding-bottom:8px}h3{font-size:14px}p{white-space:pre-wrap}a{color:#315f46;overflow-wrap:anywhere}.eyebrow{font-size:10px;letter-spacing:2px}.stamp{padding:14px;border:2px solid #b47f3d;color:#825315;font-weight:bold;margin-bottom:25px}.evidence{padding:12px 20px;border-left:3px solid #dbe7cf;background:#f7f8f2;margin:14px 0;break-inside:avoid}li{margin:7px 0;white-space:pre-wrap}@media print{body{margin:0;padding:10mm;font-size:10pt}h1{font-size:28pt}h2{font-size:16pt}a{color:inherit}.evidence{background:none}.stamp{font-size:11pt}}';
function htmlDoc(title,body){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${reportCSS}</style></head><body>${body}</body></html>`}
function filename(s){return s.replace(/[^a-z0-9_-]+/gi,'_').slice(0,70)||'Brief'}
function download(name,content,type='text/html'){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Download requested. If blocked, open the file in a regular browser.');}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Copied.')}catch{showDialog('Copy text',`<p class="tiny">Select and copy the text below.</p><textarea id="copy-fallback" rows="15" class="section-gap">${esc(s)}</textarea>`);$('#copy-fallback').select()}}
function plainReport(c){const el=document.createElement('div');el.innerHTML=reportBody(c);el.querySelectorAll('h1,h2,h3,p,li,article').forEach(x=>x.append('\n\n'));return el.textContent}
function reportDialog(c,standalone=false){showDialog(c.synthetic?'Fictional sample brief':'Client brief preview',`<div class="row" style="margin-bottom:18px">${action(standalone?'download-sample':'export-report','Download HTML','dark',c.id)}${action(standalone?'print-sample':'print-report','Print / save PDF','',c.id)}</div><p class="tiny" style="margin-bottom:15px">Open the downloaded HTML in your browser and choose Print → Save as PDF if printing is blocked in a preview.</p><div class="report-preview">${reportBody(c)}</div>`)}
function printReport(c){const w=window.open('','_blank');if(!w){toast('Popup blocked. Download HTML, then use your browser’s Print command.');return}w.document.open();w.document.write(htmlDoc(c.company,reportBody(c)));w.document.close();setTimeout(()=>{try{w.focus();w.print()}catch{}},300)}
function quoteDoc(x){const accepted=['Active','Delivered'].includes(x.stage),link=accepted?safeURL(state.settings.paymentUrl):'';return htmlDoc('Research proposal',`<div class="eyebrow">ASHYQ DALA / ${accepted?'AGREED SCOPE SUMMARY':'DRAFT PROPOSAL'}</div><h1>Company research brief</h1>${demo?'<div class="stamp">FICTIONAL EXAMPLE · Not a real invoice or payment request.</div>':''}<p>For ${esc(x.client)}<br>Subject: ${esc(x.company||'To confirm')}<br>Prepared by ${esc(state.settings.operator||'Analyst to confirm')} · ${esc(today())}</p><h2>Scope</h2><p>One Kazakh company. Review accessible, permitted company sources and the documents the buyer supplies. Deliver a concise English brief, dated source references, documented inconsistencies, limitations, and questions requiring follow-up. Source coverage will be confirmed before work begins.</p><h2>Fee and timing</h2><p>Total fee: ${money(x.fee)} USD.<br>Deposit: ${money(x.fee/2)} after written scope agreement; balance: ${money(x.fee/2)} on delivery.<br>Target delivery: two business days after source access, scope, documents, and deposit are confirmed. Unavailable sources may require a narrower scope or an agreed change in timing.<br>Any applicable taxes, extra research, and third-party fees must be agreed separately before charging.</p><h2>Acceptance and changes</h2><p>Reply with the correct company name and BIN (if known), your research question, decision deadline, and acceptance of this scope. No additional work or expense will be charged without agreement. If the agreed work cannot be delivered, agree a reduced scope or refund the undelivered portion. A specific refund amount for work already completed must be agreed in writing.</p><h2>Limits</h2><p>Commercial research only. No legal opinion, credit rating, exhaustive ownership investigation, sanctions clearance, or guarantee of safety. Land records, private financial statements, field visits, and certified translations are outside this fee. Personal data and third-party information may only be used where permitted.</p>${link&&!demo?`<h2>Payment for agreed work</h2><p>Confirm the deposit amount and USD currency on the payment page before paying. This link is provided by the analyst.</p><p><a href="${esc(link)}" rel="noopener noreferrer">Open payment page</a></p>`:'<p>Payment instructions will be provided after the scope is agreed. This document is a proposal, not a tax invoice or payment receipt.</p>'}<p>Contact: ${esc(state.settings.email||'Receiving email not configured')}</p>`)}
function documentRequest(c){return `Subject: Company documents for ${c.company}\n\nHello,\n\nWe are preparing a scoped commercial review for ${c.client}. Please confirm the exact legal name and BIN of the entity involved in this transaction, and share the documents you are authorized to disclose:\n\n1. A current company registration extract for the contracting entity.\n2. The relevant draft agreement, quotation, or invoice showing consistent company details.\n3. Any license or certificate material to the proposed work.\n4. If relevant and separately agreed, an official company tax-debt extract you can obtain and lawfully share.\n\nPlease remove unrelated personal identifiers, private addresses, and bank credentials. Do not send passwords, digital-signature files, or account access. Let us know any restrictions on client use of the documents. We will confirm scope and permitted handling before processing them.\n\nResearch question: ${c.goal}\n\nThank you,\n${state.settings.operator||'[Your name]'}\n${state.settings.email}`}
function offerHTML(){const template=atob($('#offer-template').textContent.trim()),bytes=Uint8Array.from(template,c=>c.charCodeAt(0)),html=new TextDecoder().decode(bytes);const cfg={brand:'Ashyq Dala',operator:state.settings.operator,email:state.settings.email,bookingUrl:safeURL(state.settings.bookingUrl),price:state.settings.price};const json=JSON.stringify(cfg).replace(/</g,'\\u003c');return html.replace(/(<script id="ad-config" type="application\/json">)[\s\S]*?(<\/script>)/,(_,a,b)=>a+json+b)}
function previewOffer(){showDialog('Your public sales page',`<p class="tiny" style="margin-bottom:15px">${emailOK(state.settings.email)?'Your current public settings are applied.':'Set a receiving email before sharing the page with customers.'}</p><iframe id="offer-frame" title="Public offer preview" sandbox="allow-scripts allow-popups allow-forms allow-downloads" style="width:100%;height:64vh;border:1px solid #d5dece;border-radius:8px"></iframe>`);$('#offer-frame').srcdoc=offerHTML()}
async function importJSON(file){if(!file)return;if(file.size>5000000)throw Error('File exceeds 5 MB.');const raw=JSON.parse(await file.text());if(raw.type==='ashyq-dala-intake'&&raw.version===1){if(demo)throw Error('Return to your own workspace before importing a real request.');leadDialog('',{client:short(raw.clientName)||'New request',email:short(raw.clientEmail),company:short(raw.company),notes:`Research goal: ${text(raw.goal)}\nRequested deadline: ${short(raw.deadline)}\nBIN supplied: ${short(raw.bin)}`,next:'Confirm research scope, identity, source access, and price'});return}if(raw.type!=='ashyq-dala-backup'||raw.dataset!=='own')throw Error('Choose an own-workspace backup or a supported intake request. Demo backups cannot become real work.');const restored=normalizeState(raw.data);if(demo)throw Error('Return to your own workspace before restoring real work.');if(!confirm('Replace this workspace with the backup? Download your current backup first if needed.'))return;state=restored;recoveryRaw=null;selectedCase=null;render();toast('Workspace restored.')}
function dirtyForms(){return $$('form[data-dirty="true"]').filter(f=>!f.closest('dialog')||f.closest('dialog').open)}
function guardEdits(discard=false){const forms=dirtyForms();if(!forms.length)return true;if(!discard){toast('Save your edits before opening or exporting another item.');return false}if(!confirm('Discard unsaved edits? Cancel to keep editing.'))return false;forms.forEach(f=>delete f.dataset.dirty);return true;}
document.addEventListener('input',e=>{const f=e.target.closest('form[data-form]');if(f)f.dataset.dirty='true'});
document.addEventListener('change',e=>{const f=e.target.closest('form[data-form]');if(f)f.dataset.dirty='true'});
$('#dialog').addEventListener('cancel',e=>{if(!guardEdits(true))e.preventDefault()});
window.addEventListener('beforeunload',e=>{if(dirtyForms().length){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-view]');if(!b)return;e.preventDefault();if(!guardEdits(!!b.dataset.view||['close','toggle-demo','select-case','delete-lead','delete-case','delete-evidence'].includes(b.dataset.action)))return;if(b.dataset.view){view=b.dataset.view;search='';render();return}const a=b.dataset.action,id=b.dataset.id;try{switch(a){case 'close':closeDialog();break;case 'settings':view='settings';render();break;case 'toggle-demo':toggleDemo();break;case 'new-lead':leadDialog();break;case 'edit-lead':leadDialog(id);break;case 'new-case':caseDialog();break;case 'edit-case':caseDialog(id);break;case 'select-case':selectedCase=id;render();break;case 'new-evidence':evidenceDialog();break;case 'edit-evidence':evidenceDialog(id);break;case 'csv-import':csvDialog();break;case 'csv-template':download('Evidence_import_template.csv','title,category,url,reference,accessed,sourceDate,recordBin,recordName,claim\n','text/csv');break;case 'use-prospect':{const p=prospects[Number(id)];if(p)leadDialog('',{client:p.company,notes:`Prospect, not confirmed interested.\nContact: ${p.contactUrl}\nSource: ${p.url}\nAsk for: ${p.role}\nAngle: ${p.angle}`});break}case 'lead-case':{const x=state.leads.find(x=>x.id===id),c=state.cases.find(x=>x.leadId===id);closeDialog();if(c){selectedCase=c.id;view='cases';render()}else caseDialog('',{client:x.client,company:x.company,leadId:id});break}case 'delete-lead':if(confirm('Delete this opportunity? Research cases are kept separately.')){state.leads=state.leads.filter(x=>x.id!==id);closeDialog();render()}break;case 'delete-case':if(confirm('Delete this case and its evidence?')){state.cases=state.cases.filter(x=>x.id!==id);selectedCase=null;closeDialog();render()}break;case 'delete-evidence':if(confirm('Delete this evidence record?')){const c=currentCase();c.sources=c.sources.filter(x=>x.id!==id);c.signedOff=false;closeDialog();render()}break;case 'quote':{const x=state.leads.find(x=>x.id===id);download(`Proposal_${filename(x.client)}.html`,quoteDoc(x));break}case 'sample-report':reportDialog(sampleCase(),true);break;case 'preview-report':reportDialog(state.cases.find(x=>x.id===id));break;case 'download-sample':download('Fictional_sample_brief.html',htmlDoc('Fictional sample',reportBody(sampleCase())));break;case 'export-report':{const c=state.cases.find(x=>x.id===id);download(`${c.synthetic||demo?'SAMPLE_':ready(c)?'Brief_':'DRAFT_'}${filename(c.company)}.html`,htmlDoc(c.company,reportBody(c)));break}case 'print-report':printReport(state.cases.find(x=>x.id===id));break;case 'print-sample':printReport(sampleCase());break;case 'copy-report':await copyText(plainReport(state.cases.find(x=>x.id===id)));break;case 'document-request':await copyText(documentRequest(state.cases.find(x=>x.id===id)));break;case 'copy-outreach':await copyText(outreach());break;case 'preview-offer':previewOffer();break;case 'export-offer':if(demo)throw Error('Return to your own workspace before exporting a customer-facing offer.');if(!emailOK(state.settings.email)){view='settings';render();throw Error('Add your receiving email and save settings first.')}download('Ashyq_Dala_Offer.html',offerHTML());break;case 'backup':download(`Ashyq_Dala_${demo?'DEMO':'Backup'}_${today()}.json`,JSON.stringify({type:'ashyq-dala-backup',dataset:demo?'demo':'own',exportedAt:new Date().toISOString(),data:state},null,2),'application/json');break;case 'import':$('#import-file').click();break;case 'recover-data':download('Ashyq_Dala_Recovery.json',recoveryRaw||'{}','application/json');break;case 'clear-work':if(confirm('Clear all leads, cases, and settings in this workspace? This cannot be undone without a backup.')){state=defaults();if(!demo)recoveryRaw=null;selectedCase=null;render();toast('Workspace cleared.')}break}}catch(err){toast(err.message)}});
function toggleDemo(){if(!guardEdits(true))return;closeDialog();demo=!demo;state=demo?demoState():own;selectedCase=null;view='home';render();}
$('#sample-toggle').addEventListener('click',toggleDemo);
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form)),id=form.dataset.id;try{switch(form.dataset.form){case 'settings':if(d.bookingUrl&&!safeURL(d.bookingUrl)||d.paymentUrl&&!safeURL(d.paymentUrl))throw Error('Booking and payment links must be HTTPS URLs without credentials.');state.settings={operator:short(d.operator),email:short(d.email),bookingUrl:safeURL(d.bookingUrl),paymentUrl:safeURL(d.paymentUrl),price:Number(d.price),goal:Number(d.goal),hourlyValue:Number(d.hourlyValue),startDate:d.startDate};render();toast('Settings saved. You can now export your sales page.');break;case 'lead':{if(Number(d.received)>Number(d.fee))throw Error('Cash received cannot exceed the recorded fee. Update the fee or receipt amount.');const old=state.leads.find(x=>x.id===id),x={id:id||uid(),client:short(d.client),email:short(d.email),company:short(d.company),stage:d.stage,fee:Number(d.fee),received:Number(d.received),cost:Number(d.cost),hours:Number(d.hours),followup:d.followup,next:short(d.next),notes:text(d.notes),createdAt:old?.createdAt||today()};if(old)Object.assign(old,x);else{if(state.leads.length>=1000)throw Error('Workspace limit: 1,000 opportunities.');state.leads.push(x);}closeDialog();render();toast('Opportunity saved.');break}case 'case':{const old=state.cases.find(x=>x.id===id),x={company:short(d.company),bin:d.bin,client:short(d.client),goal:text(d.goal),deadline:d.deadline,updatedAt:today(),signedOff:false};if(old){if(old.bin!==x.bin||old.company!==x.company)old.sources.forEach(s=>s.match='Unreviewed');Object.assign(old,x);selectedCase=old.id}else{if(state.cases.length>=500)throw Error('Workspace limit: 500 cases.');const c={id:uid(),leadId:form.dataset.lead||'',synthetic:demo,...x,summary:'',recommendations:'',limitations:'',notes:'',analyst:state.settings.operator,createdAt:today(),sources:[]};state.cases.push(c);selectedCase=c.id}closeDialog();view='cases';render();toast('Case saved.');break}case 'evidence':{const c=currentCase(),s={id:id||uid(),title:short(d.title),category:d.category,url:safeURL(d.url),reference:short(d.reference),accessed:d.accessed,sourceDate:d.sourceDate,recordBin:d.recordBin,recordName:short(d.recordName),claim:text(d.claim),match:d.match,permission:d.permission,reviewNote:text(d.reviewNote)};if(d.url&&!s.url)throw Error('Source links must use HTTPS.');if(!s.url&&!s.reference)throw Error('Provide a source URL or document reference.');if(s.match==='Confirmed'&&conflict(c,s))throw Error('Conflicting BIN: this record cannot be confirmed for the subject.');if(s.match==='Confirmed'&&!sameBIN(c,s)&&!s.reviewNote.trim())throw Error('Explain your attribution before confirming a record without an exact BIN match.');const old=c.sources.find(x=>x.id===id);if(old)Object.assign(old,s);else{if(c.sources.length>=500)throw Error('A case can contain at most 500 evidence records.');c.sources.push(s);}c.signedOff=false;c.updatedAt=today();closeDialog();render();toast('Source saved. Final review reset.');break}case 'assessment':{const c=state.cases.find(x=>x.id===id);Object.assign(c,{summary:text(d.summary),recommendations:text(d.recommendations),limitations:text(d.limitations),notes:text(d.notes),analyst:short(d.analyst),signedOff:d.signedOff==='on',updatedAt:today()});render();toast('Assessment saved.');break}case 'csv':doCSV(d.csv);break}}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='stage-filter'){stageFilter=e.target.value;render()}if(e.target.dataset.task!==undefined){const n=Number(e.target.dataset.task);state.tasks=e.target.checked?[...new Set([...state.tasks,n])]:state.tasks.filter(x=>x!==n);render()}if(e.target.id==='import-file'){await importJSON(e.target.files[0]);e.target.value=''}if(e.target.id==='csv-file'){const f=e.target.files[0];if(f?.size>2000000)throw Error('CSV exceeds 2 MB.');if(f)$('#csv-text').value=await f.text()}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='lead-search'){search=e.target.value;const pos=e.target.selectionStart;render();const el=$('#lead-search');el.focus();el.setSelectionRange(pos,pos)}});
render();
})();
